class Student <: Equatable<Student>{

    let name: String
    let grade: Int64
    let major: String
    let cources: HashMap<String, Int64>

    public init(name: String, grade: Int64, major: String) {
        this.name = name
        this.grade = grade
        this.major = major
        this.cources = HashMap<String, Int64>()
    }

    public override operator func != (that: Student): Bool {
        var flag = false
        if (this.name != that.name) {
            flag = true
        }
        if (this.grade != that.grade) {
            flag = true
        }
        if (this.major != that.major) {
            flag = true
        }
        for ((k, v) in this.cources) {
            if (!that.cources.contains(k)) {
                flag = true
            } else {
                if (v != that.cources[k]) {
                    flag = true
                }
            }
        }
        return flag
    }

    public override operator func == (that: Student): Bool {
        if (this.name != that.name) {
            return false
        }
        if (this.grade != that.grade) {
            return false
        }
        if (this.major != that.major) {
            return false
        }
        for ((k, v) in this.cources) {
            if (!that.cources.contains(k)) {
                return false
            }
            if (v != that.cources[k]) {
                return false
            }
        }
        return true
    }
}

class AssessmentSystem {

    let students: HashMap<String, Student>

    public init() {
        this.students = HashMap<String, Student>()
    }

    public func add_student(name: String, grade: Int64, major: String): Unit {
        let student = Student(name, grade, major)
        this.students[name] = student
    }

    public func add_course_score(name: String, course: String, score: Int64): Unit {
        if (this.students.contains(name)) {
            let student = this.students[name]
            student.cources[course] = score
        }
    }

    public func get_gpa(name: String): Option<Float64> {
        if (!this.students.contains(name)) {
            return None
        }
        let student = this.students[name]
        if (student.cources.size() == 0) {
            return None
        }
        var total: Float64 = 0.0
        for ((_, score) in student.cources) {
            total = total + score.cast(Float64)
        }
        let gpa = total / student.cources.size().cast(Float64)
        return Some(gpa)
    }

    public func get_all_students_with_fail_course(): ArrayList<String> {
        let result = ArrayList<String>()
        for ((name, student) in this.students) {
            for ((_, score) in student.cources) {
                if (score < 60) {
                    result.append(name)
                    break
                }
            }
        }
        return result
    }

    public func get_course_average(course: String): Option<Float64> {
        var total: Float64 = 0.0
        var count: Int64 = 0
        for ((_, student) in this.students) {
            if (student.cources.contains(course)) {
                let score = student.cources[course]
                if (score != -1) {
                    total = total + score.cast(Float64)
                    count = count + 1
                }
            }
        }
        if (count == 0) {
            return None
        }
        let average = total / count.cast(Float64)
        return Some(average)
    }

    public func get_top_student(): Option<String> {
        var top_student: Option<String> = None
        var top_gpa: Float64 = 0.0
        for ((name, _) in this.students) {
            let gpa_option = this.get_gpa(name)
            if (gpa_option.is_some()) {
                let gpa = gpa_option.unwrap()
                if (gpa > top_gpa) {
                    top_gpa = gpa
                    top_student = Some(name)
                }
            }
        }
        return top_student
    }
}

