class CalendarUtil {

    let events: ArrayList<Event>

    public init() {
        this.events = ArrayList<Event>()
    }

    public func add_event(event: Event): Unit {
        this.events.append(event)
    }

    public func remove_event(event: Event): Unit {
        for i in Range(0, this.events.size()) {
            if this.events[i] == event {
                this.events.remove_at(i)
                break
            }
        }
    }

    public func get_events(date: DateTime): ArrayList<Event> {
        let result = ArrayList<Event>()
        for event in this.events {
            if event.date.year == date.year && event.date.month == date.month && event.date.day_of_month == date.day_of_month {
                result.append(event)
            }
        }
        return result
    }

    public func is_available(start_time: DateTime, end_time: DateTime): Bool {
        for event in this.events {
            if start_time < event.end_time && end_time > event.start_time {
                return false
            }
        }
        return true
    }

    public func get_available_slots(date: DateTime): ArrayList<(DateTime, DateTime)> {
        let result = ArrayList<(DateTime, DateTime)>()
        var current_time = DateTime.of(year: date.year, month: date.month, day_of_month: date.day_of_month, hour: 0, minute: 0)
        let end_of_day = DateTime.of(year: date.year, month: date.month, day_of_month: date.day_of_month, hour: 23, minute: 59)

        while current_time <= end_of_day {
            let slot_end = current_time.plus_minutes(60)
            if this.is_available(current_time, slot_end) {
                result.append((current_time, slot_end))
            }
            current_time = current_time.plus_minutes(60)
        }

        return result
    }

    public func get_upcoming_events(num_events: Int64): ArrayList<Event> {
        let now = DateTime.now()
        let upcoming = ArrayList<Event>()
        let sorted_events = this.events.sort_by(|e| e.start_time)

        for event in sorted_events {
            if event.start_time >= now {
                upcoming.append(event)
                if upcoming.size() >= num_events {
                    break
                }
            }
        }
        return upcoming
    }
}

import std.collection.HashMap

class CamelCaseMap {

    let _data: HashMap<String, Any>

    public init() {
        _data = HashMap<String, Any>()
    }

    public func __getitem__(key: String): Any {
        return _data.get(_convert_key(key) as String) ?? nil
    }

    public func __setitem__(key: String, value: Any): Unit {
        _data.put(_convert_key(key) as String, value)
    }

    public func __delitem__(key: String): Unit {
        _data.remove(_convert_key(key) as String)
    }

    public func __len__(): Int64 {
        return _data.size()
    }

    public func _convert_key(key: Any): Any {
        if key is String {
            return CamelCaseMap._to_camel_case(key as String)
        }
        return key
    }

    public static func _to_camel_case(key: String): String {
        let parts = key.split('_')
        if parts.size() == 0 {
            return ""
        }
        let first = parts[0]
        let rest = parts.slice(1, parts.size())
        let camel_parts = rest.map(part -> part.capitalize())
        return first + camel_parts.join("")
    }
}

import std.collection.ArrayList

class ChandrasekharSieve {

    /*
    This is a class that uses the Chandrasekhar's Sieve method to find all prime numbers within the range
    */

    let n: Int64
    var primes: ArrayList<Int64> = ArrayList<Int64>()

    public init(n: Int64) {
        /*
        Initialize the ChandrasekharSieve class with the given limit.
        :param n: Int64, the upper limit for generating prime numbers
        */
        this.n = n
        this.primes = generate_primes()
    }

    public func generate_primes(): ArrayList<Int64> {
        /*
        Generate prime numbers up to the specified limit using the Chandrasekhar sieve algorithm.
        :return: ArrayList<Int64>, a list of prime numbers
        >>> cs = ChandrasekharSieve(20)
        >>> cs.generate_primes()
        [2, 3, 5, 7, 11, 13, 17, 19]

        */
        if this.n < 2 {
            return ArrayList<Int64>()
        }

        var sieve: ArrayList<Bool> = ArrayList<Bool>()
        for i in 0..this.n + 1 {
            sieve.append(true)
        }
        sieve.set(0, false)
        sieve.set(1, false)

        var p: Int64 = 2
        while p * p <= this.n {
            if sieve.get(p) == true {
                var i: Int64 = p * p
                while i <= this.n {
                    sieve.set(i, false)
                    i += p
                }
            }
            p += 1
        }

        var primes: ArrayList<Int64> = ArrayList<Int64>()
        for i in 2..this.n + 1 {
            if sieve.get(i) == true {
                primes.append(i)
            }
        }

        return primes
    }

    public func get_primes(): ArrayList<Int64> {
        /*
        Get the list of generated prime numbers.
        :return: ArrayList<Int64>, a list of prime numbers
        >>> cs = ChandrasekharSieve(20)
        >>> cs.get_primes()
        [2, 3, 5, 7, 11, 13, 17, 19]

        */
        return this.primes
    }
}

