    public func register_student(student: HashMap<String, String>): Int64 {
        for s in this.students {
            if s["name"] == student["name"] {
                return 0
            }
        }
        this.students.add(student)
        return 1
    }

    public func register_class(student_name: String, class_name: String): ArrayList<String> {
        if this.students_registration_classes.contains(student_name) {
            this.students_registration_classes[student_name].add(class_name)
        } else {
            this.students_registration_classes[student_name] = ArrayList<String>()
            this.students_registration_classes[student_name].add(class_name)
        }
        return this.students_registration_classes[student_name]
    }

    public func get_students_by_major(major: String): ArrayList<String> {
        var student_list: ArrayList<String> = ArrayList<String>()
        for student in this.students {
            if student["major"] == major {
                student_list.add(student["name"])
            }
        }
        return student_list
    }

    public func get_all_major(): ArrayList<String> {
        var major_list: ArrayList<String> = ArrayList<String>()
        for student in this.students {
            var major = student["major"]
            var exists = false
            for m in major_list {
                if m == major {
                    exists = true
                    break
                }
            }
            if !exists {
                major_list.add(major)
            }
        }
        return major_list
    }

    public func get_most_popular_class_in_major(major: String): String {
        var class_list: ArrayList<String> = ArrayList<String>()
        for student in this.students {
            if student["major"] == major {
                var name = student["name"]
                if this.students_registration_classes.contains(name) {
                    for class_name in this.students_registration_classes[name] {
                        class_list.add(class_name)
                    }
                }
            }
        }
        var count_map: HashMap<String, Int64> = HashMap<String, Int64>()
        var max_count: Int64 = 0
        var most_popular: String = ""
        for class_name in class_list {
            if count_map.contains(class_name) {
                count_map[class_name] = count_map[class_name] + 1
            } else {
                count_map[class_name] = 1
            }
            if count_map[class_name] > max_count {
                max_count = count_map[class_name]
                most_popular = class_name
            }
        }
        return most_popular
    }
}

import std.collection.ArrayList

class CombinationCalculator {

    let datas: ArrayList<String>

    public init(datas: ArrayList<String>) {
        this.datas = datas
    }

    public static func factorial(n: Int64): Int64 {
        var result = 1
        for (i in 1..n + 1) {
            result *= i
        }
        return result
    }

    public static func count(n: Int64, m: Int64): Int64 {
        if m == 0 or n == m {
            return 1
        }
        return factorial(n) / (factorial(n - m) * factorial(m))
    }

    public static func count_all(n: Int64): Int64 {
        if n < 0 or n > 63 {
            return Int64.Max
        }
        if n == 63 {
            return Int64.Max
        }
        return (1 << n) - 1
    }

    public func select(m: Int64): ArrayList<ArrayList<String>> {
        let result = ArrayList<ArrayList<String>>()
        let resultList = ArrayList<String>()
        for _ in 0..m {
            resultList.add("")
        }
        this._select(0, resultList, 0, result)
        return result
    }

    public func select_all(): ArrayList<ArrayList<String>> {
        let result = ArrayList<ArrayList<String>>()
        for i in 1..this.datas.size() + 1 {
            result.extend(this.select(i))
        }
        return result
    }

    public func _select(dataIndex: Int64, resultList: ArrayList<String>, resultIndex: Int64, result: ArrayList<ArrayList<String>>): Unit {
        let resultLen = resultList.size()
        let resultCount = resultIndex + 1
        if resultCount > resultLen {
            result.add(resultList.clone())
            return
        }
        for i in dataIndex..this.datas.size() + resultCount - resultLen {
            resultList.set(resultIndex.cast(Uint64), this.datas.get(i.cast(Uint64)))
            this._select(i + 1, resultList, resultIndex + 1, result)
        }
    }
}

