class DataStatistics2 {

    /*
    This is a class for performing data statistics, supporting to get the sum, minimum, maximum, variance, standard deviation, and correlation of a given dataset.
    */

    let data: ArrayList<Float64>

    public init(data: ArrayList<Float64>) {
        /*
        Initialize Data List
        :param data:ArrayList<Float64>
        */
        this.data = data
    }

    public func get_sum(): Float64 {
        /*
        Calculate the sum of data
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_sum()
        10.0
        */
        var sum: Float64 = 0.0
        for value in this.data {
            sum += value
        }
        return sum
    }

    public func get_min(): Float64 {
        /*
        Calculate the minimum value in the data
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_min()
        1.0
        */
        if this.data.size() == 0 {
            return 0.0
        }
        var min_val: Float64 = this.data[0]
        for value in this.data {
            if value < min_val {
                min_val = value
            }
        }
        return min_val
    }

    public func get_max(): Float64 {
        /*
        Calculate the maximum value in the data
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_max()
        4.0
        */
        if this.data.size() == 0 {
            return 0.0
        }
        var max_val: Float64 = this.data[0]
        for value in this.data {
            if value > max_val {
                max_val = value
            }
        }
        return max_val
    }

    public func get_variance(): Float64 {
        /*
        Calculate variance, accurate to two digits after the Decimal separator
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_variance()
        1.25
        */
        if this.data.size() == 0 {
            return 0.0
        }
        var mean: Float64 = this.get_sum() / this.data.size()
        var variance: Float64 = 0.0
        for value in this.data {
            variance += (value - mean) * (value - mean)
        }
        variance /= this.data.size()
        return round(variance * 100.0) / 100.0
    }

    public func get_std_deviation(): Float64 {
        /*
        Calculate standard deviation, accurate to two digits after the Decimal separator
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_std_deviation()
        1.12
        */
        var variance: Float64 = this.get_variance()
        var std_dev: Float64 = sqrt(variance)
        return round(std_dev * 100.0) / 100.0
    }

    public func get_correlation(): Float64 {
        /*
        Calculate correlation
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_correlation()
        1.0
        */
        if this.data.size() <= 1 {
            return 1.0
        }
        var mean: Float64 = this.get_sum() / this.data.size()
        var sum_xy: Float64 = 0.0
        var sum_x2: Float64 = 0.0
        var sum_y2: Float64 = 0.0
        for i in 0..this.data.size() {
            var x: Float64 = i as Float64
            var y: Float64 = this.data[i]
            sum_xy += x * y
            sum_x2 += x * x
            sum_y2 += y * y
        }
        var n: Float64 = this.data.size() as Float64
        var numerator: Float64 = n * sum_xy - this.get_sum() * (n - 1) * n / 2.0
        var denominator_x: Float64 = sqrt(n * sum_x2 - ((n - 1) * n / 2.0) * ((n - 1) * n / 2.0))
        var denominator_y: Float64 = sqrt(n * sum_y2 - this.get_sum() * this.get_sum())
        if abs(denominator_x) < 1e-10 || abs(denominator_y) < 1e-10 {
            return 0.0
        }
        var correlation: Float64 = numerator / (denominator_x * denominator_y)
        return round(correlation * 100.0) / 100.0
    }
}

import std.collection.ArrayList
