class DataStatistics4 {

    public static func correlation_coefficient(data1: ArrayList<Float64>, data2: ArrayList<Float64>): Float64 {
        let n = data1.size()
        let mean1 = data1.sum() / n
        let mean2 = data2.sum() / n

        var numerator: Float64 = 0.0
        var sum_sq1: Float64 = 0.0
        var sum_sq2: Float64 = 0.0

        for i in 0..n {
            let diff1 = data1[i] - mean1
            let diff2 = data2[i] - mean2
            numerator += diff1 * diff2
            sum_sq1 += diff1 * diff1
            sum_sq2 += diff2 * diff2
        }

        let denominator = sqrt(sum_sq1) * sqrt(sum_sq2)
        return denominator != 0.0 ? numerator / denominator : 0.0
    }

    public static func skewness(data: ArrayList<Float64>): Float64 {
        let n = data.size()
        let mean = data.sum() / n
        let variance = data.map(|x| pow(x - mean, 2.0)).sum() / n
        let std_deviation = sqrt(variance)

        if std_deviation == 0.0 {
            return 0.0
        }

        let n_float = n as Float64
        let skewness = data.map(|x| pow(x - mean, 3.0)).sum() * n_float / ((n_float - 1.0) * (n_float - 2.0) * pow(std_deviation, 3.0))
        return skewness
    }

    public static func kurtosis(data: ArrayList<Float64>): Float64 {
        let n = data.size()
        let mean = data.sum() / n
        let variance = data.map(|x| pow(x - mean, 2.0)).sum() / n
        let std_dev = sqrt(variance)

        if std_dev == 0.0 {
            return nan
        }

        let centered_data = data.map(|x| x - mean)
        let fourth_moment = centered_data.map(|x| pow(x, 4.0)).sum() / (n as Float64)
        let kurtosis_value = (fourth_moment / pow(std_dev, 4.0)) - 3.0
        return kurtosis_value
    }

    public static func pdf(data: ArrayList<Float64>, mu: Float64, sigma: Float64): ArrayList<Float64> {
        let sqrt_2pi = sqrt(2.0 * 3.141592653589793)
        let coeff = 1.0 / (sigma * sqrt_2pi)
        let result = ArrayList<Float64>()

        for x in data {
            let exponent = -0.5 * pow((x - mu) / sigma, 2.0)
            let value = coeff * exp(exponent)
            result.append(value)
        }

        return result
    }
}

import std.collection.ArrayList

class DecryptionUtils {

    /*
    This is a class that provides methods for decryption, including the Caesar cipher, Vigenere cipher, and Rail Fence cipher.
    */

    let key: String

    public init(key: String) {
        /*
        Initializes the decryption utility with a key.
        :param key: The key to use for decryption,String.
        */
        this.key = key
    }

    public func caesar_decipher(ciphertext: String, shift: Int64): String {
        /*
        Deciphers the given ciphertext using the Caesar cipher
        :param ciphertext: The ciphertext to decipher,String.
        :param shift: The shift to use for decryption,Int64.
        :return: The deciphered plaintext,String.
        >>> d = DecryptionUtils('key')
        >>> d.caesar_decipher('ifmmp', 1)
        'hello'

        */
        var plaintext: String = ""
        for char in ciphertext {
            if char.isalpha() {
                let ascii_offset: Int64 = char.isupper() ? 65 : 97
                let shifted_char: Char = Char(((Int64(char) - ascii_offset - shift) % 26 + 26) % 26 + ascii_offset)
                plaintext += String(shifted_char)
            } else {
                plaintext += String(char)
            }
        }
        return plaintext
    }

    public func vigenere_decipher(ciphertext: String): String {
        /*
        Deciphers the given ciphertext using the Vigenere cipher
        :param ciphertext: The ciphertext to decipher,String.
        :return: The deciphered plaintext,String.
        >>> d = DecryptionUtils('key')
        >>> d.vigenere_decipher('ifmmp')
        'ybocl'

        */
        var decrypted_text: String = ""
        var key_index: Int64 = 0
        for char in ciphertext {
            if char.isalpha() {
                let shift: Int64 = Int64(this.key[Int64(key_index % this.key.length())].lower()) - Int64('a')
                let base: Int64 = Int64('a')
                let lower_char: Int64 = Int64(char.lower()) - base
                let decrypted_char_code: Int64 = (lower_char - shift + 26) % 26 + base
                let decrypted_char: Char = Char(decrypted_char_code)
                decrypted_text += char.isupper() ? decrypted_char.upper() : decrypted_char
                key_index += 1
            } else {
                decrypted_text += String(char)
            }
        }
        return decrypted_text
    }

    public func rail_fence_decipher(encrypted_text: String, rails: Int64): String {
        /*
        Deciphers the given ciphertext using the Rail Fence cipher
        :param encrypted_text: The ciphertext to decipher,String.
        :param rails: The number of rails to use for decryption,Int64.
        :return: The deciphered plaintext,String.
        >>> d = DecryptionUtils('key')
        >>> d.rail_fence_decipher('Hoo!el,Wrdl l', 3)
        'Hello, World!'

        */
        if rails <= 1 || encrypted_text.length() == 0 {
            return encrypted_text
        }

        let length: Int64 = encrypted_text.length()
        var fence: ArrayList<ArrayList<Char>> = ArrayList<ArrayList<Char>>()
        for i in 0..rails {
            let row: ArrayList<Char> = ArrayList<Char>()
            for _ in 0..length {
                row.add('\n')
            }
            fence.add(row)
        }

        var direction: Int64 = -1
        var row: Int64 = 0
        var col: Int64 = 0

        for _ in 0..length {
            if row == 0 || row == rails - 1 {
                direction = -direction
            }
            fence[row][col] = ' '
            col += 1
            row += direction
        }

        var index: Int64 = 0
        for i in 0..rails {
            for j in 0..length {
                if fence[i][j] == ' ' {
                    fence[i][j] = encrypted_text[Int64(index)]
                    index += 1
                }
            }
        }

        var plain_text: String = ""
        direction = -1
        row = 0
        col = 0
        for _ in 0..length {
            if row == 0 || row == rails - 1 {
                direction = -direction
            }
            plain_text += String(fence[row][col])
            col += 1
            row += direction
        }

        return plain_text
    }
}

