class Customer {
    let name: String
    let fidelity: Int64

    public init(name: String, fidelity: Int64) {
        this.name = name
        this.fidelity = fidelity
    }
}

class DiscountStrategy {

    let customer: Customer
    let cart: ArrayList<Product>
    let promotion: (DiscountStrategy) -> Float64
    var __total: Float64

    public init(customer: Customer, cart: ArrayList<Product>, promotion!: (DiscountStrategy) -> Float64 = {_ => 0.0}) {
        this.customer = customer
        this.cart = cart
        this.promotion = promotion
        this.__total = this.total()
    }

    public func total(): Float64 {
        this.__total = 0.0
        for item in this.cart {
            this.__total += item.quantity * item.price
        }
        return this.__total
    }

    public func due(): Float64 {
        let discount = this.promotion(this)
        return this.__total - discount
    }

    public static func FidelityPromo(order: DiscountStrategy): Float64 {
        if order.customer.fidelity >= 1000 {
            return order.total() * 0.05
        } else {
            return 0.0
        }
    }

    public static func BulkItemPromo(order: DiscountStrategy): Float64 {
        var discount: Float64 = 0.0
        for item in order.cart {
            if item.quantity >= 20 {
                discount += item.quantity * item.price * 0.1
            }
        }
        return discount
    }

    public static func LargeOrderPromo(order: DiscountStrategy): Float64 {
        var uniqueProducts = ArrayList<String>()
        for item in order.cart {
            if !uniqueProducts.contains(item.name) {
                uniqueProducts.add(item.name)
            }
        }
        if uniqueProducts.size() >= 10 {
            return order.total() * 0.07
        } else {
            return 0.0
        }
    }
}

import std.collection.ArrayList

class EightPuzzle {

    let initial_state: ArrayList<ArrayList<Int64>>
    let goal_state: ArrayList<ArrayList<Int64>>

    public init(initial_state: ArrayList<ArrayList<Int64>>) {
        this.initial_state = initial_state
        this.goal_state = ArrayList<ArrayList<Int64>>([ArrayList<Int64>([1, 2, 3]), ArrayList<Int64>([4, 5, 6]), ArrayList<Int64>([7, 8, 0])])
    }

    public func find_blank(state: ArrayList<ArrayList<Int64>>): (Int64, Int64) {
        for i in 0..3 {
            for j in 0..3 {
                if state[i][j] == 0 {
                    return (i, j)
                }
            }
        }
        return (0, 0)
    }

    public func move(state: ArrayList<ArrayList<Int64>>, direction: String): ArrayList<ArrayList<Int64>> {
        let new_state = ArrayList<ArrayList<Int64>>()
        for row in state {
            let new_row = ArrayList<Int64>()
            for cell in row {
                new_row.append(cell)
            }
            new_state.append(new_row)
        }

        let (i, j) = this.find_blank(new_state)

        if direction == "up" && i > 0 {
            new_state[i][j] = new_state[i - 1][j]
            new_state[i - 1][j] = 0
        } else if direction == "down" && i < 2 {
            new_state[i][j] = new_state[i + 1][j]
            new_state[i + 1][j] = 0
        } else if direction == "left" && j > 0 {
            new_state[i][j] = new_state[i][j - 1]
            new_state[i][j - 1] = 0
        } else if direction == "right" && j < 2 {
            new_state[i][j] = new_state[i][j + 1]
            new_state[i][j + 1] = 0
        }

        return new_state
    }

    public func get_possible_moves(state: ArrayList<ArrayList<Int64>>): ArrayList<String> {
        let moves = ArrayList<String>()
        let (i, j) = this.find_blank(state)

        if i > 0 {
            moves.append("up")
        }
        if i < 2 {
            moves.append("down")
        }
        if j > 0 {
            moves.append("left")
        }
        if j < 2 {
            moves.append("right")
        }

        return moves
    }

    public func solve(): ArrayList<String> {
        let open_list = ArrayList<Tuple<ArrayList<ArrayList<Int64>>, ArrayList<String>>>()
        let closed_list = ArrayList<ArrayList<ArrayList<Int64>>>()

        open_list.append(Tuple(this.initial_state, ArrayList<String>()))

        while open_list.size() > 0 {
            let (current_state, path) = open_list.pop(0)
            closed_list.append(current_state)

            if current_state == this.goal_state {
                return path
            }

            for move in this.get_possible_moves(current_state) {
                let new_state = this.move(current_state, move)
                let is_in_closed = false
                for seen_state in closed_list {
                    if new_state == seen_state {
                        is_in_closed = true
                        break
                    }
                }
                if !is_in_closed {
                    let new_path = ArrayList<String>()
                    for step in path {
                        new_path.append(step)
                    }
                    new_path.append(move)
                    open_list.append(Tuple(new_state, new_path))
                }
            }
        }

        return ArrayList<String>()
    }
}

import std.time.DateTime
import std.collection.ArrayList
import std.collection.HashMap

class EmailClient {

    let addr: String
    let capacity: Int64
    var inbox: ArrayList<HashMap<String, Any>>

    public init(addr: String, capacity: Int64) {
        this.addr = addr
        this.capacity = capacity
        this.inbox = ArrayList<HashMap<String, Any>>()
    }

    public func send_to(recv: EmailClient, content: String, size: Int64): Bool {
        if not recv.is_full_with_one_more_email(size) {
            let timestamp = DateTime.now().format("YYYY-MM-DD hh:mm:ss")
            let email = HashMap<String, Any>()
            email.put("sender", this.addr)
            email.put("receiver", recv.addr)
            email.put("content", content)
            email.put("size", size)
            email.put("time", timestamp)
            email.put("state", "unread")
            recv.inbox.add(email)
            return true
        } else {
            this.clear_inbox(size)
            return false
        }
    }

    public func fetch(): HashMap<String, Any> {
        if this.inbox.size() == 0 {
            return null
        }
        for i in 0 ..< this.inbox.size() {
            let email = this.inbox.get(i)
            if email.get("state") == "unread" {
                email.put("state", "read")
                return email
            }
        }
        return null
    }

    public func is_full_with_one_more_email(size: Int64): Bool {
        let occupied_size = this.get_occupied_size()
        return occupied_size + size > this.capacity
    }

    public func get_occupied_size(): Int64 {
        var occupied_size: Int64 = 0
        for email in this.inbox {
            occupied_size += email.get("size").cast(Int64)
        }
        return occupied_size
    }

    public func clear_inbox(size: Int64): Unit {
        if this.inbox.size() == 0 {
            return
        }
        var freed_space: Int64 = 0
        while freed_space < size and this.inbox.size() > 0 {
            let email = this.inbox.get(0)
            freed_space += email.get("size").cast(Int64)
            this.inbox.remove(0)
        }
    }
}

import std.collection.ArrayList

class EncryptionUtils {

    /*
    This is a class that provides methods for encryption, including the Caesar cipher, Vigenere cipher, and Rail Fence cipher.
    */

    let key: String

    public init(key: String) {
        /*
        Initializes the class with a key.
        :param key: The key to use for encryption, String.
        */
        this.key = key
    }

    public func caesar_cipher(plaintext: String, shift: Int64): String {
        /*
        Encrypts the plaintext using the Caesar cipher.
        :param plaintext: The plaintext to encrypt, String.
        :param shift: The number of characters to shift each character in the plaintext, Int64.
        :return: The ciphertext, String.
        >>> e = EncryptionUtils("key")
        >>> e.caesar_cipher("abc", 1)
        'bcd'

        */
        var ciphertext: String = ""
        for char in plaintext {
            if char.isalpha() {
                let ascii_offset: Int64 = char.isupper() ? 65 : 97
                let shifted_char: String = ((ord(char) - ascii_offset + shift) % 26 + ascii_offset).chr()
                ciphertext += shifted_char
            } else {
                ciphertext += char
            }
        }
        return ciphertext
    }

    public func vigenere_cipher(plain_text: String): String {
        /*
        Encrypts the plaintext using the Vigenere cipher.
        :param plaintext: The plaintext to encrypt, String.
        :return: The ciphertext, String.
        >>> e = EncryptionUtils("key")
        >>> e.vigenere_cipher("abc")
        'kfa'

        */
        var encrypted_text: String = ""
        var key_index: Int64 = 0
        for char in plain_text {
            if char.isalpha() {
                let shift: Int64 = ord(this.key[key_index % this.key.len()].lower()) - ord('a')
                let base: Int64 = ord('a')
                let encrypted_char: String = ((ord(char.lower()) - base + shift) % 26 + base).chr()
                encrypted_text += char.isupper() ? encrypted_char.upper() : encrypted_char
                key_index += 1
            } else {
                encrypted_text += char
            }
        }
        return encrypted_text
    }

    public func rail_fence_cipher(plain_text: String, rails: Int64): String {
        /*
        Encrypts the plaintext using the Rail Fence cipher.
        :param plaintext: The plaintext to encrypt, String.
        :return: The ciphertext, String.
        >>> e = EncryptionUtils("key")
        >>> e.rail_fence_cipher("abc", 2)
        'acb'

        */
        let len: Int64 = plain_text.len()
        if rails == 1 or len <= 1 {
            return plain_text
        }
        var fence: ArrayList<ArrayList<String>> = ArrayList<ArrayList<String>>()
        for i in 0..rails {
            let row: ArrayList<String> = ArrayList<String>()
            for j in 0..len {
                row.add("\n")
            }
            fence.add(row)
        }

        var direction: Int64 = -1
        var row: Int64 = 0
        var col: Int64 = 0

        for char in plain_text {
            if row == 0 or row == rails - 1 {
                direction = -direction
            }
            fence[row][col] = char
            col += 1
            row += direction
        }

        var encrypted_text: String = ""
        for i in 0..rails {
            for j in 0..len {
                let ch: String = fence[i][j]
                if ch != "\n" {
                    encrypted_text += ch
                }
            }
        }

        return encrypted_text
    }
}

import std.math.numeric.Decimal
import std.regex.Regex
import std.collection.ArrayList
import std.collection.Deque

class ExpressionCalculator {

    let postfix_stack: ArrayList<String>
    let operat_priority: ArrayList<Int64>

    public init() {
        postfix_stack = ArrayList<String>()
        operat_priority = ArrayList<Int64>([0, 3, 2, 1, -1, 1, 0, 2])
    }

    public func calculate(expression: String): Float64 {
        self.prepare(self.transform(expression))

        let result_stack = Deque<String>()
        self.postfix_stack.reverse()

        while self.postfix_stack.size() > 0 {
            let current_op = self.postfix_stack.pop()
            if !ExpressionCalculator.is_operator(current_op) {
                let normalized_op = current_op.replace("~", "-")
                result_stack.push(normalized_op)
            } else {
                let second_value = result_stack.pop()
                let first_value = result_stack.pop()

                let normalized_first = first_value.replace("~", "-")
                let normalized_second = second_value.replace("~", "-")

                let decimal_first = Decimal(normalized_first)
                let decimal_second = Decimal(normalized_second)
                let temp_result = ExpressionCalculator._calculate(decimal_first, decimal_second, current_op)
                result_stack.push(temp_result.toString())
            }
        }

        let result_parts = result_stack.toList()
        let result_expr = result_parts.join("*")
        return eval(result_expr).toFloat64()
    }

    public func prepare(expression: String): Unit {
        let op_stack = Deque<String>([","])
        let arr = expression.toList()
        let current_index = 0
        var count = 0

        for i in 0..arr.size() {
            let current_op = arr[i]
            if ExpressionCalculator.is_operator(current_op) {
                if count > 0 {
                    let operand = arr.slice(current_index, current_index + count).join("")
                    self.postfix_stack.push(operand)
                }

                let peek_op = op_stack.peek()
                if current_op == ")" {
                    while op_stack.peek() != "(" {
                        self.postfix_stack.push(op_stack.pop())
                    }
                    op_stack.pop()
                } else {
                    while current_op != "(" && peek_op != "," && self.compare(current_op, peek_op) {
                        self.postfix_stack.push(op_stack.pop())
                        peek_op = op_stack.peek()
                    }
                    op_stack.push(current_op)
                }

                count = 0
                current_index = i + 1
            } else {
                count += 1
            }
        }

        if count > 1 || (count == 1 && !ExpressionCalculator.is_operator(arr[current_index])) {
            let operand = arr.slice(current_index, current_index + count).join("")
            self.postfix_stack.push(operand)
        }

        while op_stack.peek() != "," {
            self.postfix_stack.push(op_stack.pop())
        }
    }

    public static func is_operator(c: String): Bool {
        let operators = Set<String>(["+", "-", "*", "/", "(", ")", "%"])
        return operators.contains(c)
    }

    public func compare(cur: String, peek: String): Bool {
        var current = cur
        var top_op = peek

        if current == "%" {
            current = "/"
        }
        if top_op == "%" {
            top_op = "/"
        }

        let current_priority = self.operat_priority[Int64(ord(current[0]) - 40)]
        let peek_priority = self.operat_priority[Int64(ord(top_op[0]) - 40)]

        return peek_priority >= current_priority
    }

    public static func _calculate(first_value: Decimal, second_value: Decimal, current_op: String): Decimal {
        match current_op {
            "+" => return first_value + second_value,
            "-" => return first_value - second_value,
            "*" => return first_value * second_value,
            "/" => return first_value / second_value,
            "%" => return first_value % second_value,
            _ => throw ValueError("Unexpected operator: " + current_op)
        }
    }

    public static func transform(expression: String): String {
        var expr = Regex("\\s+").replace_all(expression, "")
        expr = Regex("=$").replace_all(expr, "")
        let arr = expr.toList()

        for i in 0..arr.size() {
            let c = arr[i]
            if c == "-" {
                if i == 0 {
                    arr[i] = "~"
                } else {
                    let prev_c = arr[i - 1]
                    if Set<String>(["+", "-", "*", "/", "(", "E", "e"]).contains(prev_c) {
                        arr[i] = "~"
                    }
                }
            }
        }

        if arr[0] == "~" && (arr.size() > 1 && arr[1] == "(") {
            arr[0] = "-"
            return "0" + arr.join("")
        } else {
            return arr.join("")
        }
    }
}

import std.collection.ArrayList
import std.collection.HashMap
import std.math.abs

class FitnessTracker {

    /*
    This is a class as fitness tracker that implements to calculate BMI (Body Mass Index) and calorie intake based on the user's height, weight, age, and sex.
    */

    let height: Float64
    let weight: Float64
    let age: Int64
    let sex: String
    let BMI_std: ArrayList<HashMap<String, ArrayList<Int64>>>

    public init(height: Float64, weight: Float64, age: Int64, sex: String) {
        /*
        Initialize the class with height, weight, age, and sex, and calculate the BMI standard based on sex, and male is 20-25, female is 19-24.
        */
        this.height = height
        this.weight = weight
        this.age = age
        this.sex = sex
        this.BMI_std = ArrayList<HashMap<String, ArrayList<Int64>>>()
        this.BMI_std.add(HashMap<String, ArrayList<Int64>>([("male", ArrayList<Int64>([20, 25]))]))
        this.BMI_std.add(HashMap<String, ArrayList<Int64>>([("female", ArrayList<Int64>([19, 24]))]))
    }

    public func get_BMI(): Float64 {
        /*
        Calculate the BMI based on the height and weight.
        :return: BMI,which is the weight divide by the square of height, Float64.
        >>> fitnessTracker = FitnessTracker(1.8, 70.0, 20, "male")
        >>> fitnessTracker.get_BMI()
        21.604938271604937

        */
        return this.weight / (this.height * this.height)
    }

    public func condition_judge(): Int64 {
        /*
        Judge the condition of the user based on the BMI standard.
        :return: 1 if the user is too fat, -1 if the user is too thin, 0 if the user is normal, Int64.
        >>> fitnessTracker = FitnessTracker(1.8, 70.0, 20, "male")
        >>> fitnessTracker.condition_judge()
        -1

        */
        let BMI = this.get_BMI()
        let BMI_range: ArrayList<Int64>
        if this.sex == "male" {
            BMI_range = this.BMI_std.get(0).get("male")
        } else {
            BMI_range = this.BMI_std.get(1).get("female")
        }
        if BMI > Float64(BMI_range.get(1)) {
            return 1
        } else if BMI < Float64(BMI_range.get(0)) {
            return -1
        } else {
            return 0
        }
    }

    public func calculate_calorie_intake(): Float64 {
        /*
        Calculate the calorie intake based on the user's condition and BMR (Basal Metabolic Rate),BMR is calculated based on the user's height, weight, age, and sex,male is Float64(10) * this.weight + 6.25 * this.height - Float64(5) * Float64(this.age) + Float64(5),female is Float64(10) * this.weight + 6.25 * this.height - Float64(5) * Float64(this.age) - Float64(161), and the calorie intake is calculated based on the BMR and the user's condition,if the user is too fat, the calorie intake is BMR * 1.2, if the user is too thin, the calorie intake is BMR * 1.6, if the user is normal, the calorie intake is BMR * 1.4.
        :return: calorie intake, Float64.
        >>> fitnessTracker = FitnessTracker(1.8, 70.0, 20, "male")
        >>> fitnessTracker.calculate_calorie_intake()
        986.0

        */
        let BMR: Float64
        if this.sex == "male" {
            BMR = Float64(10) * this.weight + 6.25 * this.height - Float64(5) * Float64(this.age) + Float64(5)
        } else {
            BMR = Float64(10) * this.weight + 6.25 * this.height - Float64(5) * Float64(this.age) - Float64(161)
        }
        let condition = this.condition_judge()
        if condition == 1 {
            return BMR * 1.2
        } else if condition == -1 {
            return BMR * 1.6
        } else {
            return BMR * 1.4
        }
    }
}

import std.collection.ArrayList

class GomokuGame {

    /*
    This class is an implementation of a Gomoku game, supporting for making moves, checking for a winner, and checking if there are five consecutive symbols on the game board.
    */

    let board_size: Int64
    let board: ArrayList<ArrayList<String>>
    var current_player: String

    public init(board_size: Int64) {
        /*
        Initializes the game with a given board size.
        It initializes the board with empty spaces and sets the current player symbol as 'X'.
        */
        this.board_size = board_size
        this.board = ArrayList<ArrayList<String>>()
        this.current_player = "X"
        for (_ in 0..board_size) {
            let row: ArrayList<String> = ArrayList<String>()
            for (_ in 0..board_size) {
                row.add(" ")
            }
            board.add(row)
        }
    }

    public func make_move(row: Int64, col: Int64): Bool {
        /*
        Makes a move at the given row and column.
        If the move is valid, it places the current player's symbol on the board
        and changes the current player to the other player (if the current player is 'X', then it becomes 'O' and vice versa).
        :param row: Int64, the row index of this move
        :param col: Int64, the column index
        return: true if the move is valid, or false otherwise.
        >>> gomokuGame = GomokuGame(10)
        >>> gomokuGame.make_move(5, 5)
        true
        >>> gomokuGame.make_move(5, 5)
        false
        */
        if (row < 0 || row >= this.board_size || col < 0 || col >= this.board_size) {
            return false
        }
        let cell: String = this.board.get(row).get(col)
        if (cell != " ") {
            return false
        }
        this.board.get(row).set(col, this.current_player)
        this.current_player = if (this.current_player == "X") { "O" } else { "X" }
        return true
    }

    public func check_winner(): Option<String> {
        /*
        Checks if there is a winner by looking for five in a row in all directions (horizontal, vertical, diagonal).
        return: the symbol of the winning player (either 'X' or 'O') if there is a winner, or None otherwise.
        >>> gomokuGame = GomokuGame(10)
        >>> moves = [(5, 5), (0, 0), (5, 4), (0, 1), (5, 3), (0, 2), (5, 2), (0, 3), (5, 1)]
        >>> for (move in moves) {
        ...     gomokuGame.make_move(move[0], move[1])
        ... }
        >>> gomokuGame.check_winner()
        'X'
        */
        let directions: ArrayList<(Int64, Int64)> = ArrayList<(Int64, Int64)>()
        directions.add((0, 1))
        directions.add((1, 0))
        directions.add((1, 1))
        directions.add((1, -1))

        for (row in 0..this.board_size) {
            for (col in 0..this.board_size) {
                let symbol: String = this.board.get(row).get(col)
                if (symbol != " ") {
                    for (direction in directions) {
                        if (this._check_five_in_a_row(row, col, direction)) {
                            return Option<String>.some(symbol)
                        }
                    }
                }
            }
        }
        return Option<String>.none()
    }

    public func _check_five_in_a_row(row: Int64, col: Int64, direction: (Int64, Int64)): Bool {
        /*
        checks if there are five consecutive symbols of the same player in a row starting from a given cell in a given direction (horizontal, vertical, diagonal).
        Counts the number of consecutive symbols in that direction starting from the given cell,
        :param row: Int64, row of the given cell
        :param col: Int64, column of the given cell
        :param direction: tuple, (Int64, Int64), named as (dx, dy). Row and col will plus several dx and dy repectively.
        :return: true if there are five consecutive symbols of the same player, and false otherwise.
        >>> gomokuGame = GomokuGame(10)
        >>> moves = [(5, 5), (0, 0), (5, 4), (0, 1), (5, 3), (0, 2), (5, 2), (0, 3), (5, 1)]
        >>> for (move in moves) {
        ...     gomokuGame.make_move(move[0], move[1])
        ... }
        >>> gomokuGame._check_five_in_a_row(5, 1, (0, 1))
        true
        >>> gomokuGame._check_five_in_a_row(5, 1, (1, 1))
        false
        */
        let dx: Int64 = direction.0
        let dy: Int64 = direction.1
        let symbol: String = this.board.get(row).get(col)
        for (i in 1..5) {
            let new_row: Int64 = row + dx * i
            let new_col: Int64 = col + dy * i
            if (new_row < 0 || new_row >= this.board_size || new_col < 0 || new_col >= this.board_size) {
                return false
            }
            if (this.board.get(new_row).get(new_col) != symbol) {
                return false
            }
        }
        return true
    }
}

import std.collection.HashMap

class Hotel {

    let name: String
    let available_rooms: HashMap<String, Int64>
    var booked_rooms: HashMap<String, HashMap<String, Int64>>

    public init(name: String, rooms: HashMap<String, Int64>) {
        this.name = name
        this.available_rooms = HashMap<String, Int64>(rooms)
        this.booked_rooms = HashMap<String, HashMap<String, Int64>>()
    }

    public func book_room(room_type: String, room_number: Int64, name: String): String {
        if !this.available_rooms.contains(room_type) {
            return "false"
        }
        let available = this.available_rooms[room_type]
        if room_number <= available {
            if !this.booked_rooms.contains(room_type) {
                this.booked_rooms[room_type] = HashMap<String, Int64>()
            }
            this.booked_rooms[room_type][name] = room_number
            this.available_rooms[room_type] = available - room_number
            return "Success!"
        } else if available != 0 {
            return available.toString()
        } else {
            return "false"
        }
    }

    public func check_in(room_type: String, room_number: Int64, name: String): Bool {
        if !this.booked_rooms.contains(room_type) {
            return false
        }
        let room_map = this.booked_rooms[room_type]
        if !room_map.contains(name) {
            return false
        }
        let booked = room_map[name]
        if room_number > booked {
            return false
        } else if room_number == booked {
            room_map.remove(name)
        } else {
            room_map[name] = booked - room_number
        }
        return true
    }

    public func check_out(room_type: String, room_number: Int64): Unit {
        if this.available_rooms.contains(room_type) {
            this.available_rooms[room_type] = this.available_rooms[room_type] + room_number
        } else {
            this.available_rooms[room_type] = room_number
        }
    }

    public func get_available_rooms(room_type: String): Int64 {
        return this.available_rooms[room_type]
    }
}

