import std.unicode.UnicodeStringExtension

class NumberWordFormatter {

    let NUMBER: Array<String>
    let NUMBER_TEEN: Array<String>
    let NUMBER_TEN: Array<String>
    let NUMBER_MORE: Array<String>
    let NUMBER_SUFFIX: Array<String>

    public init() {
        this.NUMBER = ["", "ONE", "TWO", "THREE", "FOUR", "FIVE", "SIX", "SEVEN", "EIGHT", "NINE"]
        this.NUMBER_TEEN = ["TEN", "ELEVEN", "TWELVE", "THIRTEEN", "FOURTEEN", "FIFTEEN", "SIXTEEN", "SEVENTEEN",
                            "EIGHTEEN",
                            "NINETEEN"]
        this.NUMBER_TEN = ["TEN", "TWENTY", "THIRTY", "FORTY", "FIFTY", "SIXTY", "SEVENTY", "EIGHTY", "NINETY"]
        this.NUMBER_MORE = ["", "THOUSAND", "MILLION", "BILLION"]
        this.NUMBER_SUFFIX = ["k", "w", "", "m", "", "", "b", "", "", "t", "", "", "p", "", "", "e"]
    }

    public func format(x: Option<String>): String {
        match x {
            Some(value) => {
                return this.format_string(value)
            },
            None => {
                return ""
            }
        }
    }

    public func format_string(x: String): String {
        let parts = x.split('.')
        let lstr = parts[0]
        let rstr = parts.length > 1 ? parts[1] : ""
        let lstrrev = lstr.reverse()
        let a = [""] * 5

        var lstrrev_mut = lstrrev
        if lstrrev.length % 3 == 1 {
            lstrrev_mut = lstrrev + "00"
        } else if lstrrev.length % 3 == 2 {
            lstrrev_mut = lstrrev + "0"
        }

        var lm = ""
        for i in range(0, lstrrev_mut.length // 3) {
            let chunk = lstrrev_mut.substring(3 * i, 3 * i + 3).reverse()
            a[i] = chunk
            if a[i] != "000" {
                lm = this.trans_three(a[i]) + " " + this.parse_more(i) + " " + lm
            } else {
                lm = lm + this.trans_three(a[i])
            }
        }

        let xs = rstr != "" ? "AND CENTS " + this.trans_two(rstr.zfill(2)) + " " : ""
        if lm.trim() == "" {
            return "ZERO ONLY"
        } else {
            return lm.trim() + " " + xs + "ONLY"
        }
    }

    public func trans_two(s: String): String {
        let s_padded = s.zfill(2)
        if s_padded[0] == '0' {
            return this.NUMBER[s_padded[1].digit_value()]
        } else if s_padded[0] == '1' {
            return this.NUMBER_TEEN[s_padded.to_int() - 10]
        } else if s_padded[1] == '0' {
            return this.NUMBER_TEN[s_padded[0].digit_value() - 1]
        } else {
            return this.NUMBER_TEN[s_padded[0].digit_value() - 1] + " " + this.NUMBER[s_padded[1].digit_value()]
        }
    }

    public func trans_three(s: String): String {
        if s[0] == '0' {
            return this.trans_two(s.substring(1, 3))
        } else if s.substring(1, 3) == "00" {
            return this.NUMBER[s[0].digit_value()] + " HUNDRED"
        } else {
            return this.NUMBER[s[0].digit_value()] + " HUNDRED AND " + this.trans_two(s.substring(1, 3))
        }
    }

    public func parse_more(i: Int64): String {
        return this.NUMBER_MORE[i]
    }
}

import std.collection.ArrayList
import std.convert.RadixConvertible

class NumericEntityUnescaper {

    /*
    This is a class that provides functionality to replace numeric entities with their corresponding characters in a given string.
    */

    public init() {}

    public func replace(string: String): String {
        /*
        Replaces numeric character references (HTML entities) in the input string with their corresponding Unicode characters.
        :param string: String, the input string containing numeric character references.
        :return: String, the input string with numeric character references replaced with their corresponding Unicode characters.
        >>> unescaper = NumericEntityUnescaper()
        >>> unescaper.replace("&#65;&#66;&#67;")
        'ABC'

        */
        let out = ArrayList<String>()
        var pos = 0
        let length = string.length

        while pos < length - 2 {
            if string[pos] == '&' && string[pos + 1] == '#' {
                let start = pos + 2
                var is_hex = false
                let first_char = string[start]

                if first_char == 'x' || first_char == 'X' {
                    let start = start + 1
                    is_hex = true
                    if start == length {
                        break
                    }
                }

                var end = start
                while end < length && NumericEntityUnescaper.is_hex_char(string[end]) {
                    end += 1
                }

                if end < length && string[end] == ';' {
                    try {
                        let base = is_hex ? 16 : 10
                        let entity_value = RadixConvertible.from_string(string[start..end], base)
                        out.append(String.from_char(chr(entity_value)))
                        pos = end + 1
                        continue
                    } catch {
                        // On conversion error, treat as normal text
                    }
                }
            }

            out.append(String.from_char(string[pos]))
            pos += 1
        }

        // Append remaining characters
        while pos < length {
            out.append(String.from_char(string[pos]))
            pos += 1
        }

        return String.join("", out)
    }

    public static func is_hex_char(char: Rune): Bool {
        /*
        Determines whether a given character is a hexadecimal digit.
        :param char: Rune, the character to check.
        :return: Bool, true if the character is a hexadecimal digit, false otherwise.
        >>> NumericEntityUnescaper.is_hex_char(r'a')
        true

        */
        return char.is_digit() || (char >= 'a' && char <= 'f') || (char >= 'A' && char <= 'F')
    }
}

