class PageUtil {

    /*
    PageUtil class is a versatile utility for handling pagination and search functionalities in an efficient and convenient manner.
    */

    let data: ArrayList<Int64>
    let page_size: Int64
    let total_items: Int64
    let total_pages: Int64

    public init(data: ArrayList<Int64>, page_size: Int64) {
        /*
        Initialize the PageUtil object with the given data and page size.
        :param data: ArrayList<Int64>, the data to be paginated
        :param page_size: Int64, the number of items per page
        */
        this.data = data
        this.page_size = page_size
        this.total_items = data.size
        this.total_pages = (this.total_items + page_size - 1) / page_size
    }

    public func get_page(page_number: Int64): ArrayList<Int64> {
        /*
        Retrieve a specific page of data.
        :param page_number: Int64, the page number to fetch
        :return: ArrayList<Int64>, the data on the specified page
        >>> page_util = PageUtil(ArrayList<Int64>([1, 2, 3, 4]), 1)
        >>> page_util.get_page(1)
        [1]

        */
        if page_number < 1 || page_number > this.total_pages {
            return ArrayList<Int64>()
        }
        let start_index = (page_number - 1) * this.page_size
        let end_index = start_index + this.page_size
        let result = ArrayList<Int64>()
        for i in range(start_index, min(end_index, this.total_items)) {
            result.add(this.data.get(i))
        }
        return result
    }

    public func get_page_info(page_number: Int64): Option<PageInfo> {
        /*
        Retrieve information about a specific page.
        :param page_number: Int64, the page number to fetch information about
        :return: Option<PageInfo>, containing page information such as current page number, total pages, etc.
        >>> page_util = PageUtil(ArrayList<Int64>([1, 2, 3, 4]), 1)
        >>> page_util.get_page_info(1)
        >>> PageInfo(1, 1, 4, 4, false, true, ArrayList<Int64>([1]))

        */
        if page_number < 1 || page_number > this.total_pages {
            return Option.none()
        }
        let start_index = (page_number - 1) * this.page_size
        let end_index = min(start_index + this.page_size, this.total_items)
        let page_data = ArrayList<Int64>()
        for i in range(start_index, end_index) {
            page_data.add(this.data.get(i))
        }
        let has_previous = page_number > 1
        let has_next = page_number < this.total_pages
        let page_info = PageInfo(page_number, this.page_size, this.total_pages, this.total_items, has_previous, has_next, page_data)
        return Option.some(page_info)
    }

    public func search(keyword: String): SearchInfo {
        /*
        Search for items in the data that contain the given keyword.
        :param keyword: String, the keyword to search for
        :return: SearchInfo, containing search information such as total results and matching items
        >>> page_util = PageUtil(ArrayList<Int64>([1, 2, 3, 4]), 1)
        >>> page_util.search("1")
        >>> SearchInfo("1", 1, 1, ArrayList<Int64>([1]))

        */
        let results = ArrayList<Int64>()
        for item in this.data {
            if str(item).contains(keyword) {
                results.add(item)
            }
        }
        let total_results = results.size
        let total_pages = (total_results + this.page_size - 1) / this.page_size
        return SearchInfo(keyword, total_results, total_pages, results)
    }
}

class PersonRequest {

    /*
    This class validates input personal information data and sets invalid fields to None based to specific rules.
    */

    let name: Option<String>
    let sex: Option<String>
    let phoneNumber: Option<String>

    public init(name: String, sex: String, phoneNumber: String) {
        /*
        Initialize PersonRequest object with the provided information.
        :param name: Option<String>, the name of the person
        :param sex: Option<String>, the sex of the person
        :param phoneNumber: Option<String>, the phone number of the person
        */
        this.name = _validate_name(name) 
        this.sex = _validate_sex(sex)
        this.phoneNumber = _validate_phoneNumber(phoneNumber)
    }

    public static func _validate_name(name: String): Option<String> {
        /*
        Validate the name and return it. If name is empty or exceeds 33 characters in length, set to None.
        :param name: String, the name to validate
        :return: Option<String>, the validated name or None if invalid
        */
        if name == "" {
            return None
        }
        if name.length > 33 {
            return None
        }
        return Some(name)
    }

    public static func _validate_sex(sex: String): Option<String> {
        /*
        Validate the sex and return it. If sex is not Man, Woman, or UGM, set to None.
        :param sex: String, the sex to validate
        :return: Option<String>, the validated sex or None if invalid
        */
        if sex != "Man" && sex != "Woman" && sex != "UGM" {
            return None
        }
        return Some(sex)
    }

    public static func _validate_phoneNumber(phoneNumber: String): Option<String> {
        /*
        Validate the phone number and return it. If phoneNumber is empty or not an 11 digit number, set to None.
        :param phoneNumber: String, the phone number to validate
        :return: Option<String>, the validated phone number or None if invalid
        */
        if phoneNumber == "" {
            return None
        }
        if phoneNumber.length != 11 {
            return None
        }
        for char in phoneNumber {
            if !char.is_digit() {
                return None
            }
        }
        return Some(phoneNumber)
    }
}

import std.collection.ArrayList

class PushBoxGame {

    let map: ArrayList<ArrayList<String>>
    var player_row: Int64
    var player_col: Int64
    let targets: ArrayList<ArrayList<Int64>>
    let boxes: ArrayList<ArrayList<Int64>>
    var target_count: Int64
    var is_game_over: Bool

    public init(map: ArrayList<ArrayList<String>>) {
        this.map = map
        this.player_row = 0
        this.player_col = 0
        this.targets = ArrayList<ArrayList<Int64>>()
        this.boxes = ArrayList<ArrayList<Int64>>()
        this.target_count = 0
        this.is_game_over = false

        func init_game() {
            for row in range(this.map.size()) {
                let row_list = this.map.get(row)
                for col in range(row_list.size()) {
                    let cell = row_list.get(col)
                    if cell == "O" {
                        this.player_row = row
                        this.player_col = col
                    } else if cell == "G" {
                        let target_pos = ArrayList<Int64>()
                        target_pos.add(row)
                        target_pos.add(col)
                        this.targets.add(target_pos)
                        this.target_count += 1
                    } else if cell == "X" {
                        let box_pos = ArrayList<Int64>()
                        box_pos.add(row)
                        box_pos.add(col)
                        this.boxes.add(box_pos)
                    }
                }
            }
        }
        init_game()
    }

    public func check_win(): Bool {
        var box_on_target_count = 0
        for box in this.boxes {
            for target in this.targets {
                if box.get(0) == target.get(0) && box.get(1) == target.get(1) {
                    box_on_target_count += 1
                    break
                }
            }
        }
        if box_on_target_count == this.target_count {
            this.is_game_over = true
        }
        return this.is_game_over
    }

    public func move(direction: String): Bool {
        var new_player_row = this.player_row
        var new_player_col = this.player_col

        if direction == "w" {
            new_player_row -= 1
        } else if direction == "s" {
            new_player_row += 1
        } else if direction == "a" {
            new_player_col -= 1
        } else if direction == "d" {
            new_player_col += 1
        }

        let row_count = this.map.size()
        let col_count = this.map.get(0).size()
        if new_player_row < 0 || new_player_row >= row_count || new_player_col < 0 || new_player_col >= col_count {
            return this.check_win()
        }

        if this.map.get(new_player_row).get(new_player_col) != "#" {
            var box_found = false
            var box_index = -1
            var box_row = -1
            var box_col = -1
            for i in range(this.boxes.size()) {
                let box = this.boxes.get(i)
                if box.get(0) == new_player_row && box.get(1) == new_player_col {
                    box_found = true
                    box_index = i
                    box_row = box.get(0)
                    box_col = box.get(1)
                    break
                }
            }

            if box_found {
                let push_row = new_player_row + (new_player_row - this.player_row)
                let push_col = new_player_col + (new_player_col - this.player_col)

                if push_row < 0 || push_row >= row_count || push_col < 0 || push_col >= col_count {
                    return this.check_win()
                }

                if this.map.get(push_row).get(push_col) != "#" {
                    var box_at_push_pos = false
                    for box in this.boxes {
                        if box.get(0) == push_row && box.get(1) == push_col {
                            box_at_push_pos = true
                            break
                        }
                    }
                    if !box_at_push_pos {
                        let new_box = ArrayList<Int64>()
                        new_box.add(push_row)
                        new_box.add(push_col)
                        this.boxes.set(box_index, new_box)
                        this.player_row = new_player_row
                        this.player_col = new_player_col
                    }
                }
            } else {
                this.player_row = new_player_row
                this.player_col = new_player_col
            }
        }
        return this.check_win()
    }
}

import std.regex.Regex
import std.collection.ArrayList

class RegexUtils {

    public func match_regex(pattern: String, text: String): Bool {
        let regex = Regex::new(pattern)
        let result = regex.match(text)
        if result.is_some() {
            return true
        } else {
            return false
        }
    }

    public func findall(pattern: String, text: String): ArrayList<String> {
        let regex = Regex::new(pattern)
        let mut matches = ArrayList<String>::new()
        let iter = regex.find_iter(text)
        for m in iter {
            matches.push(m.as_str())
        }
        return matches
    }

    public func split(pattern: String, text: String): ArrayList<String> {
        let regex = Regex::new(pattern)
        let result = regex.split(text)
        let mut list = ArrayList<String>::new()
        for s in result {
            list.push(s)
        }
        return list
    }

    public func sub(pattern: String, replacement: String, text: String): String {
        let regex = Regex::new(pattern)
        return regex.replace_all(text, replacement)
    }

    public func generate_email_pattern(): String {
        return #'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b'#
    }

    public func generate_phone_number_pattern(): String {
        return #'\b\d{3}-\d{3}-\d{4}\b'#
    }

    public func generate_split_sentences_pattern(): String {
        return #'[.!?][\s]{1,2}(?=[A-Z])'#
    }

    public func split_sentences(text: String): ArrayList<String> {
        let pattern = self.generate_split_sentences_pattern()
        let mut parts = self.split(pattern, text)
        let mut result = ArrayList<String>::new()
        for i in 0..parts.len() {
            let part = parts[i].strip()
            if i < parts.len() - 1 {
                result.push(part)
            } else {
                result.push(parts[i]) // Keep last part as is
            }
        }
        return result
    }

    public func validate_phone_number(phone_number: String): Bool {
        let pattern = self.generate_phone_number_pattern()
        return self.match_regex(pattern, phone_number)
    }

    public func extract_email(text: String): ArrayList<String> {
        let pattern = self.generate_email_pattern()
        return self.findall(pattern, text)
    }
}

class RPGCharacter {

    let name: String
    var hp: Int64
    var attack_power: Int64
    var defense: Int64
    var level: Int64
    var exp: Int64

    public init(name: String, hp: Int64, attack_power: Int64, defense: Int64, level!: Int64 = 1) {
        this.name = name
        this.hp = hp
        this.attack_power = attack_power
        this.defense = defense
        this.level = level
        this.exp = 0
    }

    public func attack(other_character: RPGCharacter): Unit {
        let damage = max(this.attack_power - other_character.defense, 1)
        other_character.hp -= damage
    }

    public func heal(): Int64 {
        this.hp += 10
        if this.hp > 100 {
            this.hp = 100
        }
        return this.hp
    }

    public func gain_exp(amount: Int64): Unit {
        while amount > 0 {
            let required_exp = this.level * 100
            if this.exp + amount >= required_exp {
                amount -= (required_exp - this.exp)
                this.level_up()
            } else {
                this.exp += amount
                amount = 0
            }
        }
    }

    public func level_up(): (Int64, Int64, Int64, Int64) {
        if this.level < 100 {
            this.level += 1
            this.exp = 0
            this.hp += 20
            this.attack_power += 5
            this.defense += 5
        }
        return (this.level, this.hp, this.attack_power, this.defense)
    }

    public func is_alive(): Bool {
        return this.hp > 0
    }
}

import std.collection.ArrayList
import std.collection.HashMap

class Server {

    let white_list: ArrayList<Int64>
    let send_struct: HashMap<String, Any>
    let receive_struct: HashMap<String, Any>

    public init() {
        this.white_list = ArrayList<Int64>()
        this.send_struct = HashMap<String, Any>()
        this.receive_struct = HashMap<String, Any>()
    }

    public func add_white_list(addr: Int64): Option<ArrayList<Int64>> {
        if this.white_list.contains(addr) {
            return None
        } else {
            this.white_list.add(addr)
            return Some(this.white_list)
        }
    }

    public func del_white_list(addr: Int64): Option<ArrayList<Int64>> {
        if !this.white_list.contains(addr) {
            return None
        } else {
            this.white_list.remove(addr)
            return Some(this.white_list)
        }
    }

    public func recv(info: HashMap<String, Any>): Any {
        if !info.contains("addr") || !info.contains("content") {
            return -1
        }
        let addr = info["addr"]
        if !this.white_list.contains(addr as Int64) {
            return false
        } else {
            this.receive_struct = HashMap<String, Any>()
            this.receive_struct["addr"] = addr
            this.receive_struct["content"] = info["content"]
            return this.receive_struct["content"]
        }
    }

    public func send(info: HashMap<String, Any>): Option<String> {
        if !info.contains("addr") || !info.contains("content") {
            return Some("info structure is not correct")
        } else {
            this.send_struct.clear()
            this.send_struct["addr"] = info["addr"]
            this.send_struct["content"] = info["content"]
            return None
        }
    }

    public func show(type_struct: String): Option<HashMap<String, Any>> {
        if type_struct == "send" {
            return Some(this.send_struct)
        } else if type_struct == "receive" {
            return Some(this.receive_struct)
        } else {
            return None
        }
    }
}

import std.collection.HashMap
import std.math.abs

class Item <: Equatable<Item> {

    var price: Float64
    var quantity: Int64

    public init(price: Float64, quantity: Int64) {
        this.price = price
        this.quantity = quantity
    }

    public override operator func != (that: Item): Bool {
        return this.price != that.price || this.quantity != that.quantity
    }

    public override operator func == (that: Item): Bool {
        return this.price == that.price && this.quantity == that.quantity
    }
}

class ShoppingCart {

    let items: HashMap<String, Item>

    public init() {
        items = HashMap<String, Item>()
    }

    public func add_item(item: String, price: Float64, quantity!: Int64 = 1): Unit {
        if items.contains_key(item) {
            let current_item = items.get(item)
            items.insert(item, Item(price, quantity))
        } else {
            items.insert(item, Item(price, quantity))
        }
    }

    public func remove_item(item: String, quantity!: Int64 = 1): Unit {
        if items.contains_key(item) {
            let current_item = items.get(item)
            let new_quantity = current_item.quantity - quantity
            if new_quantity <= 0 {
                items.remove(item)
            } else {
                items.insert(item, Item(current_item.price, new_quantity))
            }
        }
    }

    public func view_items(): HashMap<String, Item> {
        return items
    }

    public func total_price(): Float64 {
        var total: Float64 = 0.0
        for (key, item) in items {
            total = total + (item.price * item.quantity as Float64)
        }
        return total
    }
}

import std.collection.HashMap
import std.collection.ArrayList

class SignInSystem {

    let users: HashMap<String, Bool>

    public init() {
        users = HashMap<String, Bool>()
    }

    public func add_user(username: String): Bool {
        if users.contains(username) {
            return false
        } else {
            users.put(username, false)
            return true
        }
    }

    public func sign_in(username: String): Bool {
        if !users.contains(username) {
            return false
        } else {
            users.put(username, true)
            return true
        }
    }

    public func check_sign_in(username: String): Bool {
        if !users.contains(username) {
            return false
        } else {
            return users.get(username)
        }
    }

    public func all_signed_in(): Bool {
        for (let signed_in in users.values()) {
            if !signed_in {
                return false
            }
        }
        return true
    }

    public func all_not_signed_in(): ArrayList<String> {
        let not_signed_in_users = ArrayList<String>()
        for (let entry in users.entries()) {
            let username = entry.key()
            let signed_in = entry.value()
            if !signed_in {
                not_signed_in_users.add(username)
            }
        }
        return not_signed_in_users
    }
}

import std.collection.ArrayList
import std.random.Random

class Snake {

    var length: Int64
    let SCREEN_WIDTH: Int64
    let SCREEN_HEIGHT: Int64
    let BLOCK_SIZE: Int64
    var positions: ArrayList<ArrayList<Int64>>
    var score: Int64
    var food_position: ArrayList<Int64>

    public init(SCREEN_WIDTH: Int64, SCREEN_HEIGHT: Int64, BLOCK_SIZE: Int64, food_position: ArrayList<Int64>) {
        this.length = 1
        this.SCREEN_WIDTH = SCREEN_WIDTH
        this.SCREEN_HEIGHT = SCREEN_HEIGHT
        this.BLOCK_SIZE = BLOCK_SIZE
        this.positions = ArrayList<ArrayList<Int64>>([ArrayList<Int64>([SCREEN_WIDTH / 2, SCREEN_HEIGHT / 2])])
        this.score = 0
        this.food_position = food_position
    }

    public func move(direction: ArrayList<Int64>): Unit {
        let cur = this.positions.get(0)
        let x = direction.get(0)
        let y = direction.get(1)

        let new_x = ((cur.get(0) + (x * this.BLOCK_SIZE)) % this.SCREEN_WIDTH)
        let new_y = ((cur.get(1) + (y * this.BLOCK_SIZE)) % this.SCREEN_HEIGHT)
        let new = ArrayList<Int64>([new_x, new_y])

        if new.equals(this.food_position) {
            this.eat_food()
        }

        if this.positions.size() > 2 {
            var i = 2
            while i < this.positions.size() {
                if this.positions.get(i).equals(new) {
                    this.reset()
                    return
                }
                i = i + 1
            }
        }

        this.positions.insert(0, new)
        if this.positions.size() > this.length {
            this.positions.remove(this.positions.size() - 1)
        }
    }

    public func random_food_position(): Unit {
        while true {
            let x = Random.int64(0, this.SCREEN_WIDTH / this.BLOCK_SIZE - 1) * this.BLOCK_SIZE
            let y = Random.int64(0, this.SCREEN_HEIGHT / this.BLOCK_SIZE - 1) * this.BLOCK_SIZE
            let pos = ArrayList<Int64>([x, y])

            var on_snake = false
            var i = 0
            while i < this.positions.size() {
                if this.positions.get(i).equals(pos) {
                    on_snake = true
                    break
                }
                i = i + 1
            }

            if not on_snake {
                this.food_position = pos
                return
            }
        }
    }

    public func reset(): Unit {
        this.length = 1
        this.positions = ArrayList<ArrayList<Int64>>([ArrayList<Int64>([this.SCREEN_WIDTH / 2, this.SCREEN_HEIGHT / 2])])
        this.score = 0
        this.random_food_position()
    }

    public func eat_food(): Unit {
        this.length = this.length + 1
        this.score = this.score + 100
        this.random_food_position()
    }
}

import std.collection.ArrayList
import std.regex.Regex
import std.unicode.UnicodeStringExtension

class SplitSentence {

    public func split_sentences(sentences_string: String): ArrayList<String> {
        let pattern = Regex.new(r"(?<!\w\.\w.)(?<![A-Z][a-z]\.)(?<=\.|\?)\s")
        let parts = pattern.split(sentences_string)
        let result = ArrayList<String>.new()

        for part in parts {
            if !part.is_empty() {
                result.add(part.strip() + "")
            }
        }

        return result
    }

    public func count_words(sentence: String): Int64 {
        let cleaned = sentence.replace_all(r"[^a-zA-Z\s]", "")
        let words = cleaned.split(r"\s+")
        var count: Int64 = 0

        for word in words {
            if !word.is_empty() {
                count += 1
            }
        }

        return count
    }

    public func process_text_file(sentences_string: String): Int64 {
        let sentences = self.split_sentences(sentences_string)
        var max_count: Int64 = 0

        for sentence in sentences {
            let count = self.count_words(sentence)
            if count > max_count {
                max_count = count
            }
        }

        return max_count
    }
}

import std.collection.ArrayList
import std.collection.HashMap

class SQLGenerator {

    let table_name: String

    public init(table_name: String) {
        this.table_name = table_name
    }

    public func select(fields!: Option<ArrayList<String>> = None, condition!: Option<String> = None): String {
        let fields_str = fields match {
            None -> "*"
            Some(f) -> String.join(f, ", ")
        }
        var sql = "SELECT " + fields_str + " FROM " + this.table_name
        if condition is Some<String>(cond) {
            sql = sql + " WHERE " + cond
        }
        return sql + ";"
    }

    public func insert(data: HashMap<String, String>): String {
        let fields = String.join(data.keys(), ", ")
        let values = String.join(data.values().map(|v| "'" + v + "'"), ", ")
        return "INSERT INTO " + this.table_name + " (" + fields + ") VALUES (" + values + ");"
    }

    public func update(data: HashMap<String, String>, condition: String): String {
        let set_parts = ArrayList<String>()
        for field in data.keys() {
            set_parts.append(field + " = '" + data[field]! + "'")
        }
        let set_clause = String.join(set_parts, ", ")
        return "UPDATE " + this.table_name + " SET " + set_clause + " WHERE " + condition + ";"
    }

    public func delete(condition: String): String {
        return "DELETE FROM " + this.table_name + " WHERE " + condition + ";"
    }

    public func select_female_under_age(age: Int64): String {
        let condition = "age < " + String(age) + " AND gender = 'female'"
        return this.select(condition: Some(condition))
    }

    public func select_by_age_range(min_age: Int64, max_age: Int64): String {
        let condition = "age BETWEEN " + String(min_age) + " AND " + String(max_age)
        return this.select(condition: Some(condition))
    }
}

import std.collection.HashMap
import std.collection.ArrayList

class SQLQueryBuilder {

    public static func select(table: String, columns!: ArrayList<String> = ArrayList<String>(['*']), where_condition!: Option<HashMap<String, String>> = None): String {
        var column_str = ""
        if columns.size() == 1 && columns[0] == "*" {
            column_str = "*"
        } else {
            column_str = ""
            for i in range(columns.size()) {
                if i > 0 {
                    column_str += ", "
                }
                column_str += columns[i]
            }
        }

        var query = "SELECT " + column_str + " FROM " + table

        if where_condition.is_some() {
            var where_map = where_condition.unwrap()
            var conditions = ArrayList<String>()
            where_map.for_each(func(key: String, value: String) {
                conditions.add(key + "='" + value + "'")
            })
            var where_clause = ""
            for i in range(conditions.size()) {
                if i > 0 {
                    where_clause += " AND "
                }
                where_clause += conditions[i]
            }
            query += " WHERE " + where_clause
        }

        return query
    }

    public static func insert(table: String, data: HashMap<String, String>): String {
        var keys = ""
        var values = ""
        var first = true
        data.for_each(func(key: String, value: String) {
            if !first {
                keys += ", "
                values += ", "
            }
            keys += key
            values += "'" + value + "'"
            first = false
        })
        return "INSERT INTO " + table + " (" + keys + ") VALUES (" + values + ")"
    }

    public static func delete(table: String, where_condition!: Option<HashMap<String, String>> = None): String {
        var query = "DELETE FROM " + table

        if where_condition.is_some() {
            var where_map = where_condition.unwrap()
            var conditions = ArrayList<String>()
            where_map.for_each(func(key: String, value: String) {
                conditions.add(key + "='" + value + "'")
            })
            var where_clause = ""
            for i in range(conditions.size()) {
                if i > 0 {
                    where_clause += " AND "
                }
                where_clause += conditions[i]
            }
            query += " WHERE " + where_clause
        }

        return query
    }

    public static func update(table: String, data: HashMap<String, String>, where_condition!: Option<HashMap<String, String>> = None): String {
        var updates = ""
        var first = true
        data.for_each(func(key: String, value: String) {
            if !first {
                updates += ", "
            }
            updates += key + "='" + value + "'"
            first = false
        })

        var query = "UPDATE " + table + " SET " + updates

        if where_condition.is_some() {
            var where_map = where_condition.unwrap()
            var conditions = ArrayList<String>()
            where_map.for_each(func(key: String, value: String) {
                conditions.add(key + "='" + value + "'")
            })
            var where_clause = ""
            for i in range(conditions.size()) {
                if i > 0 {
                    where_clause += " AND "
                }
                where_clause += conditions[i]
            }
            query += " WHERE " + where_clause
        }

        return query
    }
}

import std.collection.ArrayList
import std.collection.HashMap
import std.math.abs
import std.sort.sort
import std.math.sqrt

class Statistics3 {

    public static func median(data: ArrayList<Int64>): Float64 {
        if data.is_empty() {
            return 0.0
        }
        let sorted_data = ArrayList<Int64>(data)
        sort(sorted_data)
        let n = sorted_data.size()
        if n % 2 == 1 {
            return sorted_data.get(n // 2) as Float64
        } else {
            let mid1 = sorted_data.get(n // 2 - 1) as Float64
            let mid2 = sorted_data.get(n // 2) as Float64
            return (mid1 + mid2) / 2.0
        }
    }

    public static func mode(data: ArrayList<Int64>): ArrayList<Int64> {
        if data.is_empty() {
            return ArrayList<Int64>()
        }
        let counts = HashMap<Int64, Int64>()
        for value in data {
            let current = counts.get(value).unwrap_or(0)
            counts.put(value, current + 1)
        }
        let max_count = counts.values().max().unwrap_or(0)
        let mode_values = ArrayList<Int64>()
        for (value, count) in counts {
            if count == max_count {
                mode_values.add(value)
            }
        }
        sort(mode_values)
        return mode_values
    }

    public static func correlation(x: ArrayList<Int64>, y: ArrayList<Int64>): Option<Float64> {
        if x.size() != y.size() || x.size() == 0 {
            return Option::none()
        }
        let n = x.size() as Float64
        let mean_x = Statistics3.mean(x).unwrap_or(0.0)
        let mean_y = Statistics3.mean(y).unwrap_or(0.0)

        let numerator = ref 0.0
        let sum_x_sq = ref 0.0
        let sum_y_sq = ref 0.0

        for i in 0..x.size() {
            let xi = x.get(i) as Float64
            let yi = y.get(i) as Float64
            numerator.set(numerator.get() + (xi - mean_x) * (yi - mean_y))
            sum_x_sq.set(sum_x_sq.get() + (xi - mean_x) * (xi - mean_x))
            sum_y_sq.set(sum_y_sq.get() + (yi - mean_y) * (yi - mean_y))
        }

        let denominator = sqrt(sum_x_sq.get() * sum_y_sq.get())
        if abs(denominator) < 1e-10 {
            return Option::none()
        }
        return Option::some(numerator.get() / denominator)
    }

    public static func mean(data: ArrayList<Int64>): Option<Float64> {
        if data.is_empty() {
            return Option::none()
        }
        let sum = ref 0.0
        for value in data {
            sum.set(sum.get() + (value as Float64))
        }
        return Option::some(sum.get() / (data.size() as Float64))
    }

    public static func correlation_matrix(data: ArrayList<ArrayList<Int64>>): ArrayList<ArrayList<Float64>> {
        if data.is_empty() || data.get(0).is_empty() {
            return ArrayList<ArrayList<Float64>>()
        }
        let num_columns = data.get(0).size()
        let matrix = ArrayList<ArrayList<Float64>>()

        for i in 0..num_columns {
            let row = ArrayList<Float64>()
            for j in 0..num_columns {
                let column_i = ArrayList<Int64>()
                let column_j = ArrayList<Int64>()
                for k in 0..data.size() {
                    column_i.add(data.get(k).get(i))
                    column_j.add(data.get(k).get(j))
                }
                let corr = Statistics3.correlation(column_i, column_j)
                if corr.is_some() {
                    row.add(corr.unwrap())
                } else {
                    row.add(0.0)
                }
            }
            matrix.add(row)
        }
        return matrix
    }

    public static func standard_deviation(data: ArrayList<Int64>): Option<Float64> {
        if data.size() < 2 {
            return Option::none()
        }
        let mean_value = Statistics3.mean(data).unwrap_or(0.0)
        let variance = ref 0.0
        for x in data {
            let diff = (x as Float64) - mean_value
            variance.set(variance.get() + diff * diff)
        }
        let variance_value = variance.get() / ((data.size() as Float64) - 1.0)
        return Option::some(sqrt(variance_value))
    }

    public static func z_score(data: ArrayList<Int64>): Option<ArrayList<Float64>> {
        let mean_val = Statistics3.mean(data)
        let std_dev = Statistics3.standard_deviation(data)
        if mean_val.is_none() || std_dev.is_none() || abs(std_dev.unwrap()) < 1e-10 {
            return Option::none()
        }
        let mean_value = mean_val.unwrap()
        let std_deviation = std_dev.unwrap()
        let z_scores = ArrayList<Float64>()
        for x in data {
            z_scores.add(((x as Float64) - mean_value) / std_deviation)
        }
        return Option::some(z_scores)
    }
}

