class VectorUtil {

    public static func similarity(vector_1: ArrayList<Float64>, vector_2: ArrayList<Float64>): Float64 {
        func dot_product(v1: ArrayList<Float64>, v2: ArrayList<Float64>): Float64 {
            var result: Float64 = 0.0
            for i in range(v1.size()) {
                result += v1[i] * v2[i]
            }
            return result
        }

        func norm(v: ArrayList<Float64>): Float64 {
            var sum_sq: Float64 = 0.0
            for i in range(v.size()) {
                sum_sq += v[i] * v[i]
            }
            return sqrt(sum_sq)
        }

        var norm1: Float64 = norm(vector_1)
        var norm2: Float64 = norm(vector_2)

        if norm1 == 0.0 || norm2 == 0.0 {
            return 0.0
        }

        var unit_v1: ArrayList<Float64> = ArrayList<Float64>()
        var unit_v2: ArrayList<Float64> = ArrayList<Float64>()
        for i in range(vector_1.size()) {
            unit_v1.add(vector_1[i] / norm1)
            unit_v2.add(vector_2[i] / norm2)
        }

        return dot_product(unit_v1, unit_v2)
    }

    public static func cosine_similarities(vector_1: ArrayList<Float64>, vectors_all: ArrayList<ArrayList<Float64>>): ArrayList<Float64> {
        func dot_product(v1: ArrayList<Float64>, v2: ArrayList<Float64>): Float64 {
            var result: Float64 = 0.0
            for i in range(v1.size()) {
                result += v1[i] * v2[i]
            }
            return result
        }

        func norm(v: ArrayList<Float64>): Float64 {
            var sum_sq: Float64 = 0.0
            for i in range(v.size()) {
                sum_sq += v[i] * v[i]
            }
            return sqrt(sum_sq)
        }

        var norm1: Float64 = norm(vector_1)
        var result: ArrayList<Float64> = ArrayList<Float64>()

        for vector in vectors_all {
            var norm2: Float64 = norm(vector)
            if norm1 == 0.0 || norm2 == 0.0 {
                result.add(0.0)
            } else {
                var dot: Float64 = dot_product(vector_1, vector)
                result.add(dot / (norm1 * norm2))
            }
        }

        return result
    }

    public static func n_similarity(vector_list_1: ArrayList<ArrayList<Float64>>, vector_list_2: ArrayList<ArrayList<Float64>>): Float64 {
        if vector_list_1.size() == 0 || vector_list_2.size() == 0 {
            throw Exception("At least one of the passed list is empty.")
        }

        func mean_vector(vectors: ArrayList<ArrayList<Float64>>): ArrayList<Float64> {
            var mean: ArrayList<Float64> = ArrayList<Float64>()
            var dim: Int64 = vectors[0].size()
            for i in range(dim) {
                mean.add(0.0)
            }

            for vector in vectors {
                for i in range(dim) {
                    mean[i] += vector[i]
                }
            }

            for i in range(dim) {
                mean[i] /= vectors.size()
            }

            return mean
        }

        func norm(v: ArrayList<Float64>): Float64 {
            var sum_sq: Float64 = 0.0
            for i in range(v.size()) {
                sum_sq += v[i] * v[i]
            }
            return sqrt(sum_sq)
        }

        func dot_product(v1: ArrayList<Float64>, v2: ArrayList<Float64>): Float64 {
            var result: Float64 = 0.0
            for i in range(v1.size()) {
                result += v1[i] * v2[i]
            }
            return result
        }

        var mean1: ArrayList<Float64> = mean_vector(vector_list_1)
        var mean2: ArrayList<Float64> = mean_vector(vector_list_2)

        var norm1: Float64 = norm(mean1)
        var norm2: Float64 = norm(mean2)

        if norm1 == 0.0 || norm2 == 0.0 {
            return 0.0
        }

        var unit_v1: ArrayList<Float64> = ArrayList<Float64>()
        var unit_v2: ArrayList<Float64> = ArrayList<Float64>()
        for i in range(mean1.size()) {
            unit_v1.add(mean1[i] / norm1)
            unit_v2.add(mean2[i] / norm2)
        }

        return dot_product(unit_v1, unit_v2)
    }

    public static func compute_idf_weight_dict(total_num: Int64, number_dict: HashMap<String, Float64>): HashMap<String, Float64> {
        var result: HashMap<String, Float64> = HashMap<String, Float64>()
        for entry in number_dict.entries() {
            var key: String = entry.key
            var count: Float64 = entry.value
            var weight: Float64 = log((total_num + 1.0) / (count + 1.0))
            result.put(key, weight)
        }
        return result
    }
}

import std.collection.HashMap
import std.collection.ArrayList

class Product <: Equatable<Product> {

    let price: Float64
    var quantity: Int64

    public init(price: Float64, quantity: Int64) {
        this.price = price
        this.quantity = quantity
    }

    public override operator func != (that: Product): Bool {
        return this.price != that.price || this.quantity != that.quantity
    }

    public override operator func == (that: Product): Bool {
        return this.price == that.price && this.quantity == that.quantity
    }
}

class VendingMachine {

    var inventory: HashMap<String, Product>
    var balance: Float64

    public init() {
        this.inventory = HashMap<String, Product>()
        this.balance = 0.0
    }

    public func add_item(item_name: String, price: Float64, quantity: Int64): Unit {
        if this.restock_item(item_name, quantity) {
            return
        }
        this.inventory[item_name] = Product(price, quantity)
    }

    public func insert_coin(amount: Float64): Float64 {
        this.balance += amount
        return this.balance
    }

    public func purchase_item(item_name: String): Option<Float64> {
        if this.inventory.contains(item_name) {
            var item = this.inventory[item_name]
            if item.quantity > 0 && this.balance >= item.price {
                this.balance -= item.price
                item.quantity -= 1
                return Option.some(this.balance)
            }
        }
        return Option.none()
    }

    public func restock_item(item_name: String, quantity: Int64): Bool {
        if this.inventory.contains(item_name) {
            var item = this.inventory[item_name]
            item.quantity += quantity
            return true
        }
        return false
    }

    public func display_items(): Option<String> {
        if this.inventory.is_empty() {
            return Option.none()
        }
        var items = ArrayList<String>()
        for (item_name, item_info) in this.inventory {
            items.add("${item_name} - $${item_info.price} [${item_info.quantity}]")
        }
        return Option.some(items.join("\n"))
    }
}

