    let temperature_units: String

    public init(weather: String, temperature: Float64, temperature_units: String) {
        this.weather = weather
        this.temperature = temperature
        this.temperature_units = temperature_units
    }
}

class WeatherSystem {

    var temperature: Float64
    var weather: String
    var city: String
    var weather_list: HashMap<String, Weather>

    public init(city: String) {
        this.temperature = Float64.NaN
        this.weather = ""
        this.city = city
        this.weather_list = HashMap<String, Weather>()
    }

    public func query(weather_list: HashMap<String, Weather>, tmp_units!: String = 'celsius'): Option<(Float64, String)> {
        this.weather_list = weather_list
        if !this.weather_list.contains(this.city) {
            return None
        }
        let weather_data = this.weather_list[this.city]
        this.temperature = weather_data.temperature
        this.weather = weather_data.weather
        if weather_data.temperature_units == tmp_units {
            return Some((this.temperature, this.weather))
        } else {
            if tmp_units == 'celsius' {
                return Some((this.fahrenheit_to_celsius(), this.weather))
            } else if tmp_units == 'fahrenheit' {
                return Some((this.celsius_to_fahrenheit(), this.weather))
            } else {
                return Some((this.temperature, this.weather))
            }
        }
    }

    public func set_city(city: String): Unit {
        this.city = city
    }

    public func celsius_to_fahrenheit(): Float64 {
        return (this.temperature * 9.0 / 5.0) + 32.0
    }

    public func fahrenheit_to_celsius(): Float64 {
        return (this.temperature - 32.0) * 5.0 / 9.0
    }
}

import std.collection.HashMap
import std.collection.ArrayList

class Words2Numbers {

    let numwords: HashMap<String, (Int64, Int64)>
    let units: ArrayList<String>
    let tens: ArrayList<String>
    let scales: ArrayList<String>
    let ordinal_words: HashMap<String, Int64>
    let ordinal_endings: ArrayList<(String, String)>

    public init() {
        this.numwords = HashMap<String, (Int64, Int64)>()
        this.units = ArrayList<String>(["zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen", "eighteen", "nineteen"])
        this.tens = ArrayList<String>(["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"])
        this.scales = ArrayList<String>(["hundred", "thousand", "million", "billion", "trillion"])

        this.numwords["and"] = (1, 0)
        for (idx in 0..<this.units.size) {
            this.numwords[this.units[idx]] = (1, idx)
        }
        for (idx in 0..<this.tens.size) {
            this.numwords[this.tens[idx]] = (1, idx * 10)
        }
        for (idx in 0..<this.scales.size) {
            if (idx == 0) {
                this.numwords[this.scales[idx]] = (100, 0)
            } else {
                this.numwords[this.scales[idx]] = (Int64(10.0 ** (idx * 3)), 0)
            }
        }

        this.ordinal_words = HashMap<String, Int64>()
        this.ordinal_words["first"] = 1
        this.ordinal_words["second"] = 2
        this.ordinal_words["third"] = 3
        this.ordinal_words["fifth"] = 5
        this.ordinal_words["eighth"] = 8
        this.ordinal_words["ninth"] = 9
        this.ordinal_words["twelfth"] = 12

        this.ordinal_endings = ArrayList<(String, String)>()
        this.ordinal_endings.add(("ieth", "y"))
        this.ordinal_endings.add(("th", ""))
    }

    public func text2int(textnum: String): String {
        var textnum = textnum.replace("-", " ")
        var current: Int64 = 0
        var result: Int64 = 0
        var curstring: String = ""
        var onnumber: Bool = false

        for word in textnum.split(" ") {
            if (word == "") continue

            if (this.ordinal_words.containsKey(word)) {
                let scale = this.ordinal_words[word]
                current = current * 1 + scale
                onnumber = true
            } else {
                var modifiedWord = word
                for ending in this.ordinal_endings {
                    if (word.endsWith(ending.0)) {
                        modifiedWord = word.substring(0, word.length - ending.0.length) + ending.1
                        break
                    }
                }

                if (!this.numwords.containsKey(modifiedWord)) {
                    if (onnumber) {
                        curstring += (result + current).toString() + " "
                    }
                    curstring += word + " "
                    result = 0
                    current = 0
                    onnumber = false
                } else {
                    let scale = this.numwords[modifiedWord]!.0
                    let increment = this.numwords[modifiedWord]!.1
                    current = current * scale + increment
                    if (scale > 100) {
                        result += current
                        current = 0
                    }
                    onnumber = true
                }
            }
        }

        if (onnumber) {
            curstring += (result + current).toString()
        }

        return curstring.trim()
    }

    public func is_valid_input(textnum: String): Bool {
        var textnum = textnum.replace("-", " ")

        for word in textnum.split(" ") {
            if (word == "") continue

            if (this.ordinal_words.containsKey(word)) {
                continue
            } else {
                var modifiedWord = word
                var changed = false
                for ending in this.ordinal_endings {
                    if (word.endsWith(ending.0)) {
                        modifiedWord = word.substring(0, word.length - ending.0.length) + ending.1
                        changed = true
                        break
                    }
                }

                if (changed) {
                    if (this.numwords.containsKey(modifiedWord)) {
                        continue
                    } else {
                        return false
                    }
                } else {
                    if (!this.numwords.containsKey(word)) {
                        return false
                    }
                }
            }
        }

        return true
    }
}
